# Generate output with "first 3 in row-major order shifts"
# Row-major order: (3,4), (8,11), (13,6) -> first is (3,4), so it shifts to (3,6)

h, w = 17, 19

def generate_pattern(anchor_row, anchor_col, h, w, grid):
    """Pattern generation"""
    if anchor_row >= 1:
        for c in range(max(0, anchor_col-2), min(w, anchor_col+3)):
            if c < 0: continue
            grid[anchor_row-2][c] = 5
    if anchor_row >= 1:
        for c in [anchor_col-2, anchor_col+2]:
            if 0 <= c < w:
                grid[anchor_row-1][c] = 2
    if 0 <= anchor_row < h and 0 <= anchor_col < w:
        grid[anchor_row][anchor_col] = 3
    if anchor_row+1 < h:
        for c in [anchor_col-2, anchor_col+2]:
            if 0 <= c < w:
                grid[anchor_row+1][c] = 8

out = [[0] * w for _ in range(h)]

# With "first row-major shifts": (3,4) -> (3,6), others remain
(3, 6, 3, 6)
(8, 11, 8, 11)  
(13, 6, 13, 6)

for r, c, eff_r, eff_c in [(3,4,3,6), (8,11,8,11), (13,6,13,6)]:
    generate_pattern(eff_r, eff_c, h, w, out)

# Find 3s in output
out_3s = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 3]
print("3s in output:", out_3s)

# Show the grid
print("\nOutput grid:")
for r in range(h):
    row_str = " ".join(f"{x}" for x in out[r])
    print(f"{r}: {row_str}")

